import sqlite3, os
p='/var/lib/rollout/records.sqlite3'
print('db exists:', os.path.exists(p), 'size:', os.path.getsize(p) if os.path.exists(p) else None)
if os.path.exists(p):
 c=sqlite3.connect(f'file:{p}?mode=ro', uri=True)
 print('tables:', c.execute("select name, sql from sqlite_master where type='table'").fetchall())
 for t in c.execute("select name from sqlite_master where type='table'").fetchall():
  n=t[0]
  try: print(n, 'count=', c.execute('select count(*) from "'+n.replace('"','""')+'"').fetchone()[0])
  except Exception as e: print(n, e)
 c.close()
